'use strict';
function setField(key,value){if(key in state)state[key]=value;else if(key.startsWith('report')){const map={reportFrom:'from',reportTo:'to',reportTimezone:'timezone',reportFormat:'format',reportAggregation:'aggregation'};if(map[key])reportState[map[key]]=value;if(key==='reportEquip')state.eq=value}else if(key.startsWith('notification')){const map={notificationName:'name',notificationSecretRef:'secretRef',notificationChatId:'chatId',notificationThreadId:'threadId',notificationTimezone:'timezone',notificationQuietStart:'quietStart',notificationQuietEnd:'quietEnd',notificationFilter:'stateFilter'};if(map[key])notificationState[map[key]]=value}}
document.addEventListener('change',e=>{const key=e.target.dataset.field;if(!key)return;setField(key,e.target.value);if(key==='site'){state.snapshot=null;state.history=null;state.alarms=[];const next=readableDevices()[0]?.identity.equipRef||'';state.eq=next;if(next){loadSnapshot(next);return}}if(key==='batteryObject'||key==='historyMetric'){state.history=null;if(available('getHistory'))loadHistory()}render()});
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const [action,...rest]=el.dataset.action.split(':'),value=rest.join(':');switch(action){case 'close':$('#modal').close();break;case 'refresh':await connect();break;case 'unit':state.unit=state.unit==='C'?'F':'C';render();break;case 'dictionary':metricExplain(value);break;case 'device':if(!state.devices.some(d=>d.identity.equipRef===value))return;location.hash='dashboard';await loadSnapshot(value);break;case 'step':state.configStep=Math.max(0,Math.min(5,Number(value)));render();break;case 'reportDevice':location.hash='reports';render();break;case 'reportTemplate':{const t=reportTemplates.find(t=>t.id===value);if(!t)return;reportState.template=t.id;reportState.format=t.formats[0];reportState.preview=null;render();break}case 'notificationTab':notificationState.tab=value;render();break;case 'notificationPreview':modal('测试消息范围预览',kv([['Bot显示名',esc(notificationState.name||'未填写')],['目标chatId',esc(notificationState.chatId)],['话题ID',esc(notificationState.threadId||'未指定')],['外发范围','须由平台校验并批准的设备范围'],['消息内容','测试消息正文应由受控服务生成']])+notice('仅展示当前表单目标，没有发送消息；通知平台尚未接入。'));break;case 'history':if(available('getHistory'))await loadHistory();break;case 'alarm':{const a=state.alarms.find(a=>a.occurrenceId===value);if(!a)return;modal('告警详情',kv([['描述',esc(a.message||a.title||'')],['发生时间',esc(a.occurredAt||'未知')],['活动状态',badge(a.activity)],['确认状态',badge(a.acknowledgement)],['恢复时间',esc(a.physicalClearedAt||'未恢复或无可用证据')]])+notice('变更适配尚未实现；此界面不在本地修改确认状态。'));break}default:toast('该平台操作当前不可用。')}});
window.addEventListener('hashchange',render);
render();
connect();
